-- Documentos do Recebimento: TAV (Termo de Abertura de Volumes) e Check-list de Recebimento.
-- Emitidos pelos usuários das etapas marcadas (Pré Recebimento e Contagem) enquanto a NF estiver nelas.

alter table etapas add column emite_docs_recebimento boolean not null default false;
update etapas set emite_docs_recebimento = true where ativo and setor = 'Recebimento';

create table docs_recebimento (
  id          serial primary key,
  nota_id     integer not null references notas(id) on delete cascade,
  numero_tav  integer not null,
  ano         integer not null,
  dados       jsonb not null,
  criado_por  integer references usuarios(id),
  criado_em   timestamptz not null default now()
);
create index docs_recebimento_nota on docs_recebimento (nota_id, criado_em desc);
create index docs_recebimento_tav on docs_recebimento (ano, numero_tav);

insert into modelos (chave, arquivo, nome_arquivo) values
  ('tav', decode('', 'base64'), 'tav.odt'),
  ('tav_padrao', decode('', 'base64'), 'tav.odt'),
  ('checklist', decode('', 'base64'), 'checklist-recebimento.odt'),
  ('checklist_padrao', decode('', 'base64'), 'checklist-recebimento.odt');
